var colors   =  ["#ff0100","#fab30f","#0ab4f7","#ffffff"];;  

//var colors = ["#AA2B1D","#CC561E","#EF8D32","#BECA5C"];

//var colors = ["#A03C78","#ED8E7C","#CDF3A2","#93D9A3"];

var weights = [1,1,1,1,1];

let border = 100;

let np = 5;

let graphs = [] 

function setup() {
	createCanvas(800,800);
	colorMode(HSB, 360, 100, 100,100);
	rectMode(CENTER);
	background(0);
	for(let i=0;i < 5;i++)
	{
		 let xx = random(border,width-border);
		 let yy = random(border,height-border);
		 //graphs[i] = new Graph(xx,yy);
	   graphs[i] = new Graph(width*0.5,height*0.5);
	}


	background(100);
	frameRate(60);;


}


function draw() {
	//background(100);



	for(let i=0; i < graphs.length;i++)
  {
		graphs[i].move();
	  graphs[i].display();

	}

	noFill();
	stroke(100);
	strokeWeight(300);
	ellipse(width/2,height/2,850,850);

	stroke(0);
	strokeWeight(5);
	ellipse(width/2,height/2,570,570);

}

class Graph {
  constructor(centerX,centerY) {
    this.np  = 50;
    this.x = [];
	  this.y = [];
		this.rad = 350;
    this.speed = [];
		this.dist = []
		this.direction = [];
		this.radius = [];
		this.centerX = centerX;
		this.centerY = centerY;
		this.angle = [];
		this.lineProb = random(0,1);
		let temp = colors[floor(random(0,4))];
		this.colorLines = color(hue(temp),saturation(temp) + randomGaussian()*10,brightness(temp) + randomGaussian()*10,100);
		temp = colors[floor(random(0,4))];
		this.colorFill = color(hue(temp),saturation(temp) + randomGaussian()*10,brightness(temp) + randomGaussian()*10,100);
		this.width = 1;
		noStroke();
	  for(let i=0; i < this.np;i++)
	  {
			let r       = random(0,this.rad - this.rad/10-10);
			let angle   = random(0,2*PI);
			var xx = this.centerX + r*cos(angle);
			var yy = this.centerY + r*sin(angle);
		  append(this.x,xx);
		  append(this.y,yy);
			append(this.speed,random(-0.025,0.025));
			if(random(0,1) > 0.5) 
			{
		  	append(this.direction,1);
			}else
			{
				append(this.direction,-1);
			}
			append(this.angle,angle); 
			append(this.radius,r);
	  }
  }


  move() {


		for(let i=0;i < this.np;i++)
		{

			this.angle[i] += this.direction[i]*this.speed[i];

			var xx = this.centerX + this.radius[i]*cos(this.angle[i]);
			var yy = this.centerY + this.radius[i]*sin(this.angle[i]);

			this.x[i] = xx;
			this.y[i] = yy;

		}		

	}


  display() {


		//strokeWeight(10);
		//stroke(0);
		//rect(this.centerX,this.centerY,2*this.rad,2*this.rad);


	  for(let i=0;i < this.np;i++)
		{
			if (dist(this.x[i],this.y[i],this.centerX,this.centerY) > this.rad)
			{
				this.direction[i] *= -1;
			}
		}

		if (this.lineProb < 1)
		{

			noStroke();
		beginShape();
		noFill();
		//stroke(0);
		strokeWeight(this.width);
		for(let i=0;i < this.np;i++)
		{
			curveVertex(this.x[i]-2,this.y[i]);
		}
		endShape();

    beginShape();
		noFill();
		stroke(this.colorLines);
		strokeWeight(this.width);
		for(let i=0;i < this.np;i++)
		{
			curveVertex(this.x[i],this.y[i]);
		}
		endShape();


		beginShape();
		fill(this.colorFill);
		strokeWeight(this.width);
		for(let i=0;i < this.np/2;i++)
		{
			curveVertex(this.x[i],this.y[i]);
		}
		endShape(CLOSE);
		}else
		{


				beginShape();
		    noFill();
		    stroke(0);
		    strokeWeight(1);
				for(let i=0;i < this.np;i++)
				{
					curveVertex(this.x[i]-1,this.y[i]);
				}
				endShape();

		}




	}
}

